using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class SuperMartProbe{static SuperMartProbe(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("SuperMartProbe.request"))return;File.Delete("SuperMartProbe.request");try{var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.name.ToLower()=="building"||f.name.ToLower().Contains("super")||f.name.ToLower().Contains("mart")).ToArray();var target=all.Single(f=>f.name=="building");var matches=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.sharedMesh&&f.sharedMesh.vertexCount==target.sharedMesh.vertexCount).ToArray();File.WriteAllLines("FinalEnvironmentRoadReview/SuperMartProbe.txt",matches.Select(f=>f.name+" root="+f.transform.root.name+" bounds="+f.GetComponent<Renderer>().bounds+" mesh="+AssetDatabase.GetAssetPath(f.sharedMesh)+" material="+AssetDatabase.GetAssetPath(f.GetComponent<Renderer>().sharedMaterial)+" transform="+f.transform.localToWorldMatrix));var td=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{target.sharedMesh});var ps=(Vector3[])td.GetType().GetField("p").GetValue(td);var uv=(Vector2[][])td.GetType().GetField("uv").GetValue(td);var ids=(int[])td.GetType().GetField("ids").GetValue(td);File.WriteAllLines("FinalEnvironmentRoadReview/SuperMartVertices.csv",new[]{"i,x,y,z,u,v"}.Concat(Enumerable.Range(0,ps.Length).Select(i=>{var w=target.transform.TransformPoint(ps[i]);return i+","+w.x+","+w.y+","+w.z+","+uv[0][i].x+","+uv[0][i].y;})));File.WriteAllText("FinalEnvironmentRoadReview/SuperMartIds.txt",string.Join(",",ids));foreach(var f in matches){var b=f.GetComponent<Renderer>().bounds;typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{s,b.center+new Vector3(-85,5,0),b.center,"SuperMart-FrontMinusX-"+f.GetInstanceID()});}}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/SuperMartProbe.txt",e.ToString());}}}


